    home = out / 'index.html'
    home.write_text(home.read_text().replace('<section class="wrap network-intro', promo + '<section class="wrap network-intro', 1).replace('</head>', '<link rel="stylesheet" href="/assets/before-disappears.css"></head>', 1))
    for path in ('explore/index.html', 'project-kit/index.html', 'second-invoice/index.html'):
        target = out / path
        if target.exists():
            target.write_text(target.read_text().replace('</main>', '<section class="wrap ll-tool-link"><h2>Before the work gets covered.</h2><p>Know which photos and questions are worth keeping in a private project notebook.</p><a href="/before-it-disappears/">Open Before It Disappears →</a></section></main>', 1).replace('</head>', '<link rel="stylesheet" href="/assets/before-disappears.css"></head>', 1))
